{
  "arguments": [
    {
      "claim": "The killings, beatings, and arson committed in Ljuboten constitute war crimes of wilful killing, torture or inhuman treatment, and extensive destruction of property.",
      "reasoning": "Article 8 of the Rome Statute lists \"Wilful killing;\" \"Torture or inhuman treatment, including biological experiments;\" and \"Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;\" as war crimes. The factual record shows unarmed civilians were shot dead, subjected to beatings and cruel treatment, and their homes were set on fire without any demonstrated military necessity, satisfying each listed element.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Wilful killing;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Torture or inhuman treatment, including biological experiments;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        }
      ]
    },
    {
      "claim": "The hostilities between Macedonian security forces and the NLA meet the threshold of an armed conflict not of an international character, so Article 8(c) of the Rome Statute applies.",
      "reasoning": "Article 8 states that \"In the case of an armed conflict not of an international character, serious violations of article 3 common to the four Geneva Conventions…\" are war crimes. The facts describe organized armed groups (the NLA), sustained hostilities (land‑mine attack, use of APCs, mortar support), and a level of intensity beyond isolated disturbances, which under customary IHL is sufficient to characterize the situation as a non‑international armed conflict. Consequently, the listed violations fall within the scope of Article 8(c).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "In the case of an armed conflict not of an international character, serious violations of article 3 common to the four Geneva Conventions of 12 August 1949, namely, any of the following acts committed against persons taking no active part in the hostilities"
        }
      ]
    },
    {
      "claim": "Johan Tarčulovski is individually criminally responsible for the war crimes committed in Ljuboten.",
      "reasoning": "Customary rule 151 provides that \"Individuals are criminally responsible for war crimes they commit.\" Tarčulovski personally commanded the police unit, was present during the attacks, and ordered or permitted the unlawful acts. The defence of superior orders is unavailable because Article 33(1) of the Rome Statute declares that following an order \"shall not relieve that person of criminal responsibility unless\" (and no exemption applies here). Moreover, the self‑defence justification in Article 31(1)(c) does not excuse war crimes, as it states that participation in a defensive operation \"shall not in itself constitute a ground for excluding criminal responsibility.\"",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 151,
          "quoted_text": "Individuals are criminally responsible for war crimes they commit."
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "33(1)",
          "quoted_text": "The fact that a crime within the jurisdiction of the Court has been committed by a person pursuant to an order of a Government or of a superior, whether military or civilian, shall not relieve that person of criminal responsibility unless:"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "31(1)(c)",
          "quoted_text": "The fact that the person was involved in a defensive operation conducted by forces shall not in itself constitute a ground for excluding criminal responsibility under this subparagraph;"
        }
      ]
    },
    {
      "claim": "As the commander of the operation, Tarčulovski bears command responsibility for the crimes committed by the police subordinates.",
      "reasoning": "Customary rule 152 establishes that \"Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders.\" Tarčulovski exercised effective control over the reserve police and the private security unit, directed their entry into Ljuboten, and failed to prevent or punish the unlawful killings, beatings, and arson. This omission satisfies the requisite elements of command responsibility under customary IHL.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        }
      ]
    }
  ]
}

