{
  "arguments": [
    {
      "claim": "The events in Ljuboten occurred in the context of an armed conflict not of an international character, so Article 8(2)(c) of the Rome Statute applies.",
      "reasoning": "Customary international law recognises that the existence of an organised armed group (the NLA) engaged in sustained hostilities with state security forces, together with the intensity of the fighting (land‑mine attack, use of APCs and mortar support), satisfies the threshold of a non‑international armed conflict. Because such a conflict existed, the serious violations listed in Article 8(2)(c) are war crimes within the Court’s jurisdiction.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "In the case of an armed conflict not of an international character, serious violations of article 3 common to the four Geneva Conventions of 12 August 1949, namely, any of the following acts committed against persons taking no active part in the hostilities..."
        }
      ]
    },
    {
      "claim": "The killings, beatings, and arson committed by the police in Ljuboten constitute war crimes of wilful killing, torture or inhuman treatment, and extensive destruction of property.",
      "reasoning": "Article 8(2)(b) of the Rome Statute enumerates these acts as war crimes. The factual record shows unarmed civilians were deliberately shot dead (wilful killing), were beaten, threatened with knives and subjected to cruel treatment (torture or inhuman treatment), and their homes were set alight and destroyed without any demonstrated military necessity (extensive destruction of property). Each element of the listed crimes is satisfied by the evidence.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Wilful killing; Torture or inhuman treatment, including biological experiments; Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        }
      ]
    },
    {
      "claim": "Johan Tarčulovski is individually criminally responsible for the war crimes committed in Ljuboten.",
      "reasoning": "Customary rule 151 establishes individual criminal responsibility for war crimes. Tarčulovski personally commanded the police unit, was present during the unlawful acts and either ordered or permitted them. Article 33(1) of the Rome Statute makes clear that the defence of superior orders does not relieve a person of responsibility for crimes committed pursuant to those orders, and no exemption applies here.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 151,
          "quoted_text": "Individuals are criminally responsible for war crimes they commit."
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "33(1)",
          "quoted_text": "The fact that a crime within the jurisdiction of the Court has been committed by a person pursuant to an order of a Government or of a superior, whether military or civilian, shall not relieve that person of criminal responsibility unless:"
        }
      ]
    },
    {
      "claim": "Tarčulovski bears command responsibility because he gave orders that authorised the unlawful killings, beatings and arson, and therefore is criminally liable for those war crimes.",
      "reasoning": "Customary rule 152 imposes liability on commanders and other superiors for war crimes committed pursuant to their orders. The evidence shows that Tarčulovski directed the police to enter Ljuboten with incendiary material, to fire into houses and to detain civilians, actions that directly resulted in the prohibited conduct. By issuing those orders, he satisfied the ‘pursuant to their orders’ element of command responsibility. The lack of a defence based on superior orders is reinforced by Article 33(1) of the Rome Statute.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        },
        {
          "type": "treaty",
